using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using UnityEngine;using EchoSphere.Core;using EchoSphere.Runtime;
public static class MetaResetAcceptance
{
 public static object Main(){
  const BindingFlags F=BindingFlags.Instance|BindingFlags.Static|BindingFlags.Public|BindingFlags.NonPublic;var r=UnityEngine.Object.FindAnyObjectByType<EchoSphereRuntime>();var t=r.GetType();object Get(string n)=>t.GetField(n,F).GetValue(r);void Set(string n,object v)=>t.GetField(n,F).SetValue(r,v);object Call(string n,params object[] a)=>t.GetMethod(n,F).Invoke(r,a);
  string Key(string method,EchoRegionId region)=>(string)t.GetMethod(method,F).Invoke(null,new object[]{region});var integerKeys=new List<string>{"echosphere_gold"};var stringKeys=new List<string>{"echosphere_meta_wallet_v1","echosphere_meta_wallet_backup_v1","echosphere_meta_wallet_recovery","echosphere_knowledge_v1"};for(int i=0;i<6;i++){var region=(EchoRegionId)i;foreach(string method in new[]{"RegionStabilizedKey","RegionEndlessKey","RegionMasteryKey"})integerKeys.Add(Key(method,region));stringKeys.Add(Key("RegionChallengesKey",region));}
  var ints=integerKeys.ToDictionary(k=>k,k=>new{Had=PlayerPrefs.HasKey(k),Value=PlayerPrefs.GetInt(k)});var strings=stringKeys.ToDictionary(k=>k,k=>new{Had=PlayerPrefs.HasKey(k),Value=PlayerPrefs.GetString(k,"")});var names=new[]{"_metaWallet","_metaWalletRaw","_metaEntitlementsRaw","_knowledgeLoaded"};var before=names.ToDictionary(n=>n,Get);var known=(HashSet<string>)Get("_knownKnowledgeIds");var records=known.ToArray();int checks=0;void A(bool v,string why){checks++;if(!v)throw new Exception(why);}
  try{
   foreach(string key in integerKeys)PlayerPrefs.SetInt(key,1);foreach(string key in stringKeys.Where(k=>k.StartsWith("echo-sphere:region:")))PlayerPrefs.SetString(key,"fixture");Call("ClearRegionalProgressKeys");
   foreach(string key in integerKeys.Where(k=>k!="echosphere_gold"))A(!PlayerPrefs.HasKey(key),"clears all six region integer keys");foreach(string key in stringKeys.Where(k=>k.StartsWith("echo-sphere:region:")))A(!PlayerPrefs.HasKey(key),"clears all six contract keys");
   Call("ClearMetaWallet");PlayerPrefs.DeleteKey("echosphere_gold");PlayerPrefs.DeleteKey("echosphere_knowledge_v1");known.Clear();Set("_knowledgeLoaded",true);Call("InitializeMetaProgression");A((int)Call("GetMetaBalance",CurrencyId.Credits)==0&&(int)Call("GetMetaBalance",CurrencyId.ResonanceShards)==0&&(int)Call("GetMetaBalance",CurrencyId.ArchiveData)==0,"reset cannot resurrect legacy rewards");
   var result=new{result="PASS",checks,scope="Actual wallet/regional reset helpers and remigration;all original typed keys and cached records restored,no full user reset invoked"};File.WriteAllText(Path.Combine(Application.dataPath,"../Library/meta-reset-acceptance.json"),Newtonsoft.Json.JsonConvert.SerializeObject(result));return result;
  }finally{known.Clear();known.UnionWith(records);foreach(var pair in before)Set(pair.Key,pair.Value);foreach(var pair in ints){if(pair.Value.Had)PlayerPrefs.SetInt(pair.Key,pair.Value.Value);else PlayerPrefs.DeleteKey(pair.Key);}foreach(var pair in strings){if(pair.Value.Had)PlayerPrefs.SetString(pair.Key,pair.Value.Value);else PlayerPrefs.DeleteKey(pair.Key);}PlayerPrefs.Save();foreach(var pair in ints)if(PlayerPrefs.HasKey(pair.Key)!=pair.Value.Had||(pair.Value.Had&&PlayerPrefs.GetInt(pair.Key)!=pair.Value.Value))throw new Exception("Int restore failed");foreach(var pair in strings)if(PlayerPrefs.HasKey(pair.Key)!=pair.Value.Had||(pair.Value.Had&&PlayerPrefs.GetString(pair.Key)!=pair.Value.Value))throw new Exception("String restore failed");}
 }
}
